<?php get_header();$page=max(1,absint(eph_input('pagina','1')));$args=['post_type'=>'post','post_status'=>'publish','has_password'=>false,'posts_per_page'=>9,'paged'=>$page];if(eph_input('pesquisa')!=='')$args['s']=eph_input('pesquisa');$posts=new WP_Query($args); ?>
<main class="eph-public-page"><p class="eph-eyebrow">A vida do arquivo</p><h1>Publicações</h1><p class="eph-lead">Notícias, exposições e histórias a partir do acervo. Para consultar documentos e imagens, visite o <a href="<?php echo esc_url(home_url('/catalogo/')); ?>">catálogo</a>.</p>
<form class="eph-global-search eph-directory-search" action="<?php echo esc_url(get_permalink()); ?>" method="get"><label class="screen-reader-text" for="editorial-search">Pesquisar publicações</label><input id="editorial-search" name="pesquisa" type="search" placeholder="Pesquisar publicações…" value="<?php echo esc_attr(eph_input('pesquisa')); ?>"><button>Pesquisar</button></form>
<?php foreach($posts->posts as $entry): ?>
<article class="eph-editorial-row"><?php if(has_post_thumbnail($entry)): ?><a href="<?php echo esc_url(get_permalink($entry)); ?>"><?php echo get_the_post_thumbnail($entry,'medium_large',['loading'=>'lazy','alt'=>'']); ?></a><?php endif; ?><div><p class="eph-meta"><?php echo esc_html(get_the_date('j F Y',$entry)); ?></p><h2><a href="<?php echo esc_url(get_permalink($entry)); ?>"><?php echo esc_html($entry->post_title); ?></a></h2><p><?php echo esc_html(wp_trim_words(strip_shortcodes(wp_strip_all_tags($entry->post_content)),35)); ?></p><a class="eph-more" href="<?php echo esc_url(get_permalink($entry)); ?>">Ler publicação →</a></div></article>
<?php endforeach; if(!$posts->found_posts): ?><p>Não foram encontradas publicações. <a href="<?php echo esc_url(get_permalink()); ?>">Ver todas as publicações</a>.</p><?php endif; eph_pagination($posts->max_num_pages,$page); ?>
</main><?php get_footer(); ?>
